// Aggregate several HA home-energy sensors into ONE retained topic the
// watch subscribes to: watch/energy/state.
//
// EDIT this ROLES map to your entity_ids (keep in lock-step with the
// entity list on the 'energy sensors changed' node). Every listed entity
// must appear here, or it's ignored.
const ROLES = {
  'sensor.home_battery_soc':        'batt',   // home battery %, 0..100
  'sensor.solar_power':             'solar',  // solar production, W (kW auto-scaled)
  'sensor.grid_power':              'grid',   // grid power, W SIGNED: + import / - export
  'binary_sensor.home_battery_charging': 'chg' // 'on' => charging
  // --- If your grid is split into two positive sensors, DROP 'grid' above
  //     and use these two instead (grid = import - export):
  // , 'sensor.grid_import': 'grid_import'   // W >= 0
  // , 'sensor.grid_export': 'grid_export'   // W >= 0
};

const s = (msg.data && msg.data.new_state) ? msg.data.new_state
        : (msg.payload && msg.payload.entity_id) ? msg.payload : null;
if (!s || !s.entity_id) return null;
const role = ROLES[s.entity_id];
if (!role) return null;

const numOf = (st) => { const n = Number(st.state); return isFinite(n) ? n : null; };
// numeric power in WATTS, auto-scaling kW -> W from the unit attribute.
const wattsOf = (st) => {
  let n = numOf(st); if (n === null) return null;
  const u = ((st.attributes && st.attributes.unit_of_measurement) || '').toLowerCase();
  if (u === 'kw') n *= 1000;
  return Math.round(n);
};

const store = flow.get('energy') || {};
switch (role) {
  case 'batt': {
    const n = numOf(s);
    store.batt = (n === null) ? null : Math.max(0, Math.min(100, Math.round(n)));
    break;
  }
  case 'solar':       store.solar = wattsOf(s); break;
  case 'grid':        store.grid  = wattsOf(s); break;
  case 'grid_import': store.gimp  = wattsOf(s); break;
  case 'grid_export': store.gexp  = wattsOf(s); break;
  case 'chg': {
    const v = (typeof s.state === 'string') ? s.state.toLowerCase() : s.state;
    store.chg = (v === 'on' || v === true || v === 'charging' || v === 'true');
    break;
  }
}
flow.set('energy', store);

// Signed grid: prefer the single signed sensor; else derive from split ones.
let grid = store.grid;
if (grid === undefined || grid === null) {
  if (store.gimp !== undefined || store.gexp !== undefined) {
    grid = (store.gimp || 0) - (store.gexp || 0);
  }
}

const out = {
  battery_pct: (store.batt  != null ? store.batt  : null),
  solar_w:     (store.solar != null ? store.solar : null),
  grid_w:      (grid        != null ? grid        : null),
  charging:    (store.chg === true)
};

return { topic: 'watch/energy/state', payload: JSON.stringify(out), qos: 0, retain: true };
